/**
 * 反映射：象形文字->加德纳代码
 * 别名键（同一字符的另一种写法）不参与反映射，以保证 codeOf() 对既有字符
 * 仍返回其正式键名：
 *   · "J…"  —— AA 组（Unicode AA001…）的等价单字母写法：J1 ≡ AA1、J80 ≡ Aa80
 *   · "Y1v" —— Y1a 的旋转/翻转变体写法
 */
function isAliasKey(key) {
  return key.charAt(0) === "J" || key === "Y1v";
}
const revGardiner = {};
Object.keys(GARDINER).forEach(key => {
  if (isAliasKey(key)) return;
  revGardiner[GARDINER[key]] = key;
});

/**
 * 别名键 → 正式键名（J1 → AA1、J80 → Aa80、Y1v → Y1a）。
 * 由 revGardiner 反查得到，随表内容自动保持同步。
 */
const aliasCanonical = {};
const aliasCanonicalLower = {};
Object.keys(GARDINER).forEach(key => {
  if (!isAliasKey(key)) return;
  const canon = revGardiner[GARDINER[key]];
  if (!canon) return;
  aliasCanonical[key] = canon;
  aliasCanonicalLower[key.toLowerCase()] = canon;
});

/**
 * 码的别名写法 → 正式写法（"J1" → "AA1"、"J80" → "Aa80"、"Y1v" → "Y1a"）。
 * 非别名或未收录者原样返回；大小写宽容（"j1c" → "AA1c"）。
 * @param {string} code
 * @returns {string}
 */
function canonicalCode(code) {
  if (!code) return code;
  return aliasCanonical[code] || aliasCanonicalLower[String(code).toLowerCase()] || code;
}

/**
 * 把一串 MdC 中的别名码改写为正式写法（J… → AA…/Aa…、Y1v → Y1a）。
 * · 只改写码 token；"<...>" 文本区整体原样保留（含 "\>" 转义）；
 * · 其余分隔符（- : * { } ( ) $ 等）原样保留；
 * · 连字名 {…} 内的码同样改写（连字表按正式名登记）。
 * @param {string} text
 * @returns {string}
 */
function canonicalize(text) {
  if (!text) return text;
  let out = "";
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (ch === "<") {
      let j = i + 1;
      let buf = "<";
      while (j < text.length) {
        if (text[j] === "\\" && j + 1 < text.length) { buf += text[j] + text[j + 1]; j += 2; continue; }
        buf += text[j];
        if (text[j] === ">") { j++; break; }
        j++;
      }
      out += buf;
      i = j;
      continue;
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i;
      while (j < text.length && /[A-Za-z0-9]/.test(text[j])) j++;
      out += canonicalCode(text.slice(i, j));
      i = j;
      continue;
    }
    out += ch;
    i++;
  }
  return out;
}

    // 连字表：name -> Ligature 实例（见 semantics.js）
const LIGATURES = {};


/**
 * 注册（或覆盖）一个连字。
 * 连字名 = 字符组合（如 "G39-X1"），用 "-" 连接 1-3 个字符；
 * 连字名内的分隔符统一为 "-"：":" 与 "*" 都归一化为 "-"。
 * @param {string} name 连字名（{name} 引用）
 * @param {Array<{code:string, dx:number, dy:number, scale:number}>} parts
 *   parts[0] 通常是基准字符（dx=0, dy=0, scale=1）；
 *   其余字符按 dx/dy 相对方块左下角定位、按 scale 缩放。
 * @param {string} [pron] 连字发音（可检索但不能单独成词），如 "Dd"；无发音则省略
 * @returns {{name:string, parts:Array, pron:(string|undefined)}}
 */
function defineLigature(name, parts, pron) {
    // 连字内 ":" 与 "*" 视为 "-"；各段别名码规范化为正式名
    const key = name.replace(/[:*]/g, "-").split("-").map(canonicalCode).join("-");
    LIGATURES[key] = { name: key, parts: parts, pron: pron };
    console.log("[ligature] " + key + " =", JSON.stringify(parts), pron ? "(发音 " + pron + ")" : "");
    return LIGATURES[key];
}

