        decodeCode: decodeCode,
        charOf: hg,
        codeOf: g,
        /** 别名码 → 正式名（J1 → AA1、Y1v → Y1a）；非别名原样返回。 */
        canonicalCode: canonicalCode,
        /** 把一串 MdC 中的别名码改写为正式名（文本区 "<...>" 内不改写）。 */
        canonicalize: canonicalize,

        // ---- 数据 ----
        GARDINER: GARDINER,
        revGardiner: revGardiner,
        LIGATURES: LIGATURES,
